-- =============================================================================
-- MEDEASY PHARMACY OS - 1,000 ESSENTIAL MASTER MEDICINES CATALOG (INDIA)
-- Real Brand Names, Generics/Salts, Manufacturers, HSN 300490, 12% GST & MRPs
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS "pg_trgm";
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS master_medicines (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(255) NOT NULL,
    generic_name VARCHAR(255) NOT NULL,
    category VARCHAR(100) NOT NULL DEFAULT 'Allopathy',
    form VARCHAR(50) NOT NULL DEFAULT 'Tablet',
    manufacturer VARCHAR(150) NOT NULL,
    pack_size VARCHAR(50) DEFAULT '10 tablets',
    gst_rate NUMERIC(5,2) NOT NULL DEFAULT 12.00,
    hsn_code VARCHAR(50) NOT NULL DEFAULT '300490',
    typical_mrp NUMERIC(10,2) NOT NULL DEFAULT 0.00,
    requires_prescription BOOLEAN NOT NULL DEFAULT false,
    barcode VARCHAR(100),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_master_med_name ON master_medicines(name);
CREATE INDEX IF NOT EXISTS idx_master_med_generic ON master_medicines(generic_name);
CREATE INDEX IF NOT EXISTS idx_master_med_name_trgm ON master_medicines USING gin (name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_master_med_generic_trgm ON master_medicines USING gin (generic_name gin_trgm_ops);

TRUNCATE TABLE master_medicines;











